//! H8: property checks for the snippet's highlight offsets over arbitrary UTF-8.
//!
//! The snippet is the one place the engine hands a renderer byte ranges, and the
//! ranges are found by case-insensitive search over text the builder never chose:
//! accented letters, scripts without spaces, emoji, combining marks, bidi controls.
//! Case folding can change byte length (`İ` lower-cases to two code points, `ß` to
//! `ss`), so the interesting failures are a range in the middle of a `char` and a
//! range past the end of the string the caller will slice.
//!
//! The input is generated by a seeded xorshift rather than `proptest`: the property is
//! the same, and the crate keeps its zero dev-dependency build (the workspace has no
//! vendored proptest, and a nightly-only harness is not worth a lockfile entry for
//! this). The seed is fixed, so a failure is a reproduction.
use alloc::string::{String, ToString};
use alloc::vec::Vec;

use crate::index::snippet;

/// xorshift64*: eight lines, deterministic, good enough to shuffle an alphabet.
struct Rng(u64);

impl Rng {
    fn next(&mut self) -> u64 {
        let mut x = self.0;
        x ^= x >> 12;
        x ^= x << 25;
        x ^= x >> 27;
        self.0 = x;
        x.wrapping_mul(0x2545_f491_4f6c_dd1d)
    }

    fn below(&mut self, bound: usize) -> usize {
        if bound == 0 {
            0
        } else {
            (self.next() % bound as u64) as usize
        }
    }
}

/// Every character class that has broken a highlight somewhere: the length-changing
/// folds, scripts without spaces, marks, controls and the bidi overrides.
const ALPHABET: &[&str] = &[
    "a", "b", "c", "z", "A", "Z", "0", "9", " ", "\n", "-", "_", ".", ",", "/", "'", "à", "é", "ü",
    "ñ", "ß", "İ", "ı", "中", "文", "語", "日", "本", "😀", "🎉", "\u{301}", "\u{202e}",
    "\u{200b}", "\u{feff}", "\u{9b}", "\u{1f}", "…",
];

fn random_text(rng: &mut Rng, units: usize) -> String {
    let mut text = String::new();
    for _ in 0..units {
        text.push_str(ALPHABET[rng.below(ALPHABET.len())]);
    }
    text
}

/// A term taken from the text itself (so it matches) or one built at random (so it
/// exercises the no-match path), always at a `char` boundary.
fn random_terms(rng: &mut Rng, text: &str) -> Vec<String> {
    let mut terms = Vec::new();
    let boundaries: Vec<usize> = text.char_indices().map(|(at, _)| at).collect();
    if boundaries.is_empty() {
        return terms;
    }
    for _ in 0..rng.below(4) {
        let start = boundaries[rng.below(boundaries.len())];
        let take = 1 + rng.below(6);
        let mut end = start;
        for (at, ch) in text[start..].char_indices().take(take) {
            end = start + at + ch.len_utf8();
        }
        if end > start {
            terms.push(text[start..end].to_string());
        }
    }
    if rng.below(3) == 0 {
        let units = 1 + rng.below(4);
        terms.push(random_text(rng, units));
    }
    terms
}

#[test]
fn every_range_is_inside_the_snippet_and_on_a_char_boundary() {
    let mut rng = Rng(0x5eed_1234_abcd_ef01);
    for round in 0..600 {
        let units = rng.below(400);
        let text = random_text(&mut rng, units);
        let terms = random_terms(&mut rng, &text);
        let (out, ranges) = snippet(&text, &terms);
        assert!(
            out.len() <= text.len() + 8,
            "round {round}: the snippet cannot grow past the text plus the two ellipses"
        );
        let mut previous_end = 0u32;
        for (start, end) in &ranges {
            assert!(
                start < end,
                "round {round}: empty or reversed range {start}..{end}"
            );
            assert!(
                (*end as usize) <= out.len(),
                "round {round}: range {start}..{end} past the {} byte snippet",
                out.len()
            );
            assert!(
                out.is_char_boundary(*start as usize),
                "round {round}: {start} splits a char in {:?}",
                out
            );
            assert!(
                out.is_char_boundary(*end as usize),
                "round {round}: {end} splits a char in {:?}",
                out
            );
            assert!(
                *start >= previous_end,
                "round {round}: ranges overlap or are unsorted at {start}"
            );
            previous_end = *end;
        }
    }
}

#[test]
fn the_length_changing_folds_do_not_break_a_range() {
    // Each pair is a text and the term whose fold has a different byte length.
    let cases = [
        ("İstanbul İstanbul", "i̇stanbul"),
        ("Straße Straße", "strasse"),
        ("ß ß ß", "ss"),
        ("😀clap😀clap", "clap"),
        ("a\u{301}b a\u{301}b", "a\u{301}b"),
        ("\u{202e}reversed\u{202e}", "reversed"),
        ("中文语料 中文语料", "中文"),
    ];
    for (text, term) in cases {
        let (out, ranges) = snippet(text, &[term.to_string()]);
        assert!(!out.is_empty(), "{text:?} produced no snippet");
        for (start, end) in ranges {
            assert!(start < end);
            assert!((end as usize) <= out.len());
            assert!(out.is_char_boundary(start as usize));
            assert!(out.is_char_boundary(end as usize));
        }
    }
}

#[test]
fn an_empty_page_or_term_is_not_a_range() {
    assert_eq!(
        snippet("", &["walkdir".to_string()]),
        (String::new(), Vec::new())
    );
    let (out, ranges) = snippet("walkdir", &[String::new()]);
    assert_eq!(out, "walkdir");
    assert!(ranges.is_empty());
}
